/**
 * Get the price intensity factor (-1 to 1)
 * Negative values indicate price is down, positive indicates price is up
 * @param {object} animState - Current animation state
 * @returns {number} Price intensity from -1 (very down) to 1 (very up)
 */
function getPriceIntensity(animState) {
    const cumulativeChange = getCumulativePriceChange(animState);
    // Map cumulative change to -1 to 1 range, clamped at ±50%
    const clampedChange = constrain(cumulativeChange, -50, 50);
    return clampedChange / 50;
}

/**
 * Apply depth effect to a color based on wave position and price status
 * - When price is down (intensity < 0): darken troughs more (low wavePosition)
 * - When price is up (intensity > 0): brighten peaks more (high wavePosition)
 * 
 * @param {p5.Color} baseColor - The original color from the palette
 * @param {number} wavePosition - Wave position from 0 (trough) to 1 (peak)
 * @param {number} priceIntensity - Price intensity from -1 (down) to 1 (up)
 * @returns {p5.Color} Modified color with depth effect applied
 */
function applyDepthEffect(baseColor, wavePosition, priceIntensity) {
    // Extract RGB from p5 color
    const r = red(baseColor);
    const g = green(baseColor);
    const b = blue(baseColor);

    // Convert to HSL for easier lightness manipulation
    const hsl = rgbToHsl(r, g, b);

    let lightnessModifier = 0;

    if (priceIntensity < 0) {
        // Price is DOWN - darken the troughs (low wave positions)
        // The more negative priceIntensity, the darker the troughs
        // troughFactor is 1 at wavePosition=0, 0 at wavePosition=1
        const troughFactor = 1 - wavePosition;
        // Use smoothstep for more natural falloff
        const smoothTrough = troughFactor * troughFactor * (3 - 2 * troughFactor);
        // Maximum darkening: reduce lightness by up to 60% at full intensity
        lightnessModifier = smoothTrough * priceIntensity * 0.6;
    } else if (priceIntensity > 0) {
        // Price is UP - brighten the peaks (high wave positions)
        // The more positive priceIntensity, the brighter the peaks
        // peakFactor is 0 at wavePosition=0, 1 at wavePosition=1
        const peakFactor = wavePosition;
        // Use smoothstep for more natural falloff
        const smoothPeak = peakFactor * peakFactor * (3 - 2 * peakFactor);
        // Maximum brightening: increase lightness by up to 50% at full intensity
        lightnessModifier = smoothPeak * priceIntensity * 0.5;
    }

    // Apply lightness modification
    let newLightness = hsl.l + lightnessModifier;
    newLightness = constrain(newLightness, 0.02, 0.98); // Keep within valid range

    // Convert back to RGB
    const newRgb = hslToRgb(hsl.h, hsl.s, newLightness);

    return color(newRgb.r, newRgb.g, newRgb.b);
}

/**
 * Interpolate price intensity between current and next animation states
