function getCurrentPriceIntensity(animState) {
    const currentIntensity = getPriceIntensityForIndex(animState.currentIndex);
    const nextIntensity = getPriceIntensityForIndex(
        Math.min(animState.nextIndex, pairPriceChanges.length - 1)
    );

    // Smoothstep interpolation
    const smoothFrac = animState.fraction * animState.fraction * (3 - 2 * animState.fraction);
    return lerp(currentIntensity, nextIntensity, smoothFrac);
}

/**
 * Get price intensity for a specific index in the price history
