function getPriceIntensityForIndex(index) {
    const priceData = pairPriceData[pair].priceData;
    const firstPrice = priceData[0];
    const currentPrice = priceData[index];
    const cumulativeChange = firstPrice === 0 ? 0 : ((currentPrice - firstPrice) / firstPrice) * 100;
