    return clampedChange / 50;
}

// calculate price changes for a pair
function calculatePriceChanges(pairName) {
    const priceData = pairPriceData[pairName].priceData;
    const priceChanges = [];

    for (let i = 0; i < priceData.length; i++) {
        if (i === 0) {
            priceChanges.push({
                currentPrice: priceData[i],
                previousPrice: null,
                change: 0,
                changePercent: 0
            });
        } else {
            const currentPrice = priceData[i];
            const previousPrice = priceData[i - 1];
            const change = currentPrice - previousPrice;
            const changePercent = previousPrice === 0 ? 0 : (change / previousPrice) * 100;

            priceChanges.push({
                currentPrice: currentPrice,
                previousPrice: previousPrice,
                change: change,
                changePercent: changePercent
            });
        }
    }

    return priceChanges;
}

// get current animation state (for timeline mode)
function getAnimationState() {
    const tSec = millis() / 1000;
    const totalMonths = pairPriceChanges.length;

    // Handle single price point - no animation possible
    if (totalMonths <= 1) {
        return {
            currentIndex: 0,
            nextIndex: 0,
            fraction: 0,
            loopedTime: 0
        };
    }

    if (!timeline_mode) {
        const latestIndex = totalMonths - 1;
        return {
            currentIndex: latestIndex,
            nextIndex: latestIndex,
            fraction: 0,
            loopedTime: 0
        };
    }

    const totalDuration = (totalMonths - 1) * SECS_PER_MONTH;

    const loopedTime = tSec % totalDuration;

    const pos = loopedTime / SECS_PER_MONTH;
    const currentIndex = Math.floor(pos);
    const fraction = pos - currentIndex;

    return {
        currentIndex: currentIndex,
        nextIndex: currentIndex + 1,
        fraction: fraction,
        loopedTime: loopedTime
    };
}

// cumulative price change from start to current point
function getCumulativePriceChange(animState) {
    const priceData = pairPriceData[pair].priceData;
    const firstPrice = priceData[0];
    const currentPrice = priceData[animState.currentIndex];
    const cumulativeChange = firstPrice === 0 ? 0 : ((currentPrice - firstPrice) / firstPrice) * 100;
    return cumulativeChange;
}

