/**
 * Calculate the position of the progress indicator square
 * The square travels clockwise around the border, starting from top center
 * @param {number} progress - Progress through the cycle (0 to 1)
 * @param {number} canvasSize - Size of the canvas
 * @param {number} borderSize - Size of the border (and the square)
 * @returns {object} {x, y} position of the square's top-left corner
 */
function getProgressIndicatorPosition(progress, canvasSize, borderSize) {
    // The square travels along a rectangular path in the border region
    // Path corners (top-left of square): (0,0), (canvasSize-borderSize,0), 
    //   (canvasSize-borderSize, canvasSize-borderSize), (0, canvasSize-borderSize)

    const pathLength = canvasSize - borderSize;
    const halfPath = canvasSize / 2 - borderSize / 2;
    const totalPerimeter = 4 * pathLength;
    const distance = progress * totalPerimeter;

    // Cumulative distances at segment boundaries
    const seg1End = halfPath;                    // top center to top right
    const seg2End = seg1End + pathLength;        // down right edge
    const seg3End = seg2End + pathLength;        // across bottom (right to left)
    const seg4End = seg3End + pathLength;        // up left edge
    // seg5 returns to top center

    let x, y;

    if (distance <= seg1End) {
        // Top edge: center to right
        x = canvasSize / 2 - borderSize / 2 + distance;
        y = 0;
    } else if (distance <= seg2End) {
        // Right edge: top to bottom
        x = canvasSize - borderSize;
        y = distance - seg1End;
    } else if (distance <= seg3End) {
        // Bottom edge: right to left
        x = canvasSize - borderSize - (distance - seg2End);
        y = canvasSize - borderSize;
    } else if (distance <= seg4End) {
        // Left edge: bottom to top
        x = 0;
        y = canvasSize - borderSize - (distance - seg3End);
    } else {
        // Top edge: left to center
        x = distance - seg4End;
        y = 0;
    }

    return { x, y };
}

/**
 * Draw the progress indicator square when in timeline mode
 * @param {number} canvasSize - Size of the canvas
 * @param {number} borderSize - Size of the border
 */
function drawProgressIndicator(canvasSize, borderSize) {
    // Only draw if we have a visible border
    if (borderSize <= 0) return;

    // Calculate cycle progress
    const tSec = millis() / 1000;
    const totalMonths = pairPriceChanges.length;

    // Handle single price point - no animation, show indicator at start
    if (totalMonths <= 1) {
        const pos = getProgressIndicatorPosition(0, canvasSize, borderSize);
        noStroke();
        fill(216, 216, 216);
        rect(pos.x, pos.y, borderSize, borderSize);
        return;
    }

    const totalDuration = (totalMonths - 1) * SECS_PER_MONTH;
    const loopedTime = tSec % totalDuration;
    const progress = loopedTime / totalDuration;

    // Get position for the progress indicator
    const pos = getProgressIndicatorPosition(progress, canvasSize, borderSize);

    // Draw square 10% darker than border color (240 * 0.9 = 216)
    noStroke();
    fill(216, 216, 216);
    rect(pos.x, pos.y, borderSize, borderSize);
}

