    // Calculate perimeter and positions
    const perimeterWidth = infoWidth - borderSmileySize;
    const perimeterHeight = infoHeight - borderSmileySize;
    const totalPerimeter = 2 * perimeterWidth + 2 * perimeterHeight;

    // Calculate number of faces that fit around the border
    const numFaces = Math.floor(totalPerimeter / smileySpacingBorder);

    // Animation offset - slow clockwise movement
    const animSpeed = 0.00002;
    const animOffset = (millis() * animSpeed) % 1;

    for (let i = 0; i < numFaces; i++) {
      // Calculate position along perimeter (0 to 1)
      let t = ((i / numFaces) + animOffset) % 1;
      let distance = t * totalPerimeter;

      let faceX, faceY;

      // Top edge (left to right)
      if (distance < perimeterWidth) {
        faceX = infoX + distance;
        faceY = infoY;
      }
      // Right edge (top to bottom)
      else if (distance < perimeterWidth + perimeterHeight) {
        faceX = infoX + perimeterWidth;
        faceY = infoY + (distance - perimeterWidth);
    }
    // Bottom edge (right to left)
    else if (distance < 2 * perimeterWidth + perimeterHeight) {
      faceX = infoX + perimeterWidth - (distance - perimeterWidth - perimeterHeight);
      faceY = infoY + perimeterHeight;
    }
    // Left edge (bottom to top)
    else {
      faceX = infoX;
      faceY = infoY + perimeterHeight - (distance - 2 * perimeterWidth - perimeterHeight);
