function interferencePattern(x, y, cellSize) {
  // normalize coords
  let nx = x / gridSize;
  let ny = y / gridSize;

  let wave1 = sin(nx * PI * 3 + time * 0.02) * 0.5 + 0.5;
  let wave2 = sin(ny * PI * 2 + time * 0.015) * 0.5 + 0.5;
  let wave3 = sin((nx + ny) * PI * 4 + time * 0.025) * 0.5 + 0.5;
  let wave4 = sin(sqrt(nx*nx + ny*ny) * PI * 6 + time * 0.03) * 0.5 + 0.5;

  let combined = (wave1 * 0.3 + wave2 * 0.3 + wave3 * 0.2 + wave4 * 0.2);

  // add some interference patterns
  let interference = sin(interferenceDirection *nx * PI * interferenceBaseFrequency + interferenceDirection * ny * PI * (3*interferenceBaseFrequency/4) + time * 0.01) * 0.1;
  combined += interference;

  combined = constrain(combined, 0, 1);

  const palette = pairPriceData[pair].palette;

  const paletteIndex = combined * (palette.length - 1);
  const lowerIndex = floor(paletteIndex);
  const upperIndex = min(lowerIndex + 1, palette.length - 1);
  const fraction = paletteIndex - lowerIndex;

  const color1 = color(palette[lowerIndex]);
  const color2 = color(palette[upperIndex]);

  const baseColor = lerpColor(color1, color2, fraction);

  // Apply depth effect based on wave position and price status
  // combined (0-1) represents wave position: 0 = trough, 1 = peak
  const animState = getAnimationState();
  const priceIntensity = getCurrentPriceIntensity(animState);
  const finalColor = applyDepthEffect(baseColor, combined, priceIntensity);

  fill(finalColor);
  noStroke();
  rect(x * cellSize, y * cellSize, cellSize, cellSize);
}

function radialGradientPattern(x, y, cellSize) {
  let nx = x / gridSize;
  let ny = y / gridSize;

  let centerX = 0.5;
  let centerY = 0.5;

  let dx = nx - centerX;
  let dy = ny - centerY;
  let dist = sqrt(dx * dx + dy * dy);

  let wave1 = sin(dist * PI * 8 - time * 0.04) * 0.5 + 0.5;
  let wave2 = sin(dist * PI * 12 - time * 0.03) * 0.5 + 0.5;
  let wave3 = sin(dist * PI * 16 - time * 0.05) * 0.5 + 0.5;


  let combined = wave1 * 0.4 + wave2 * 0.35 + wave3 * 0.25;

  let baseGradient = 1.0 - constrain(dist * 1.5, 0, 1);
  combined = combined * 0.8 + baseGradient * 0.2;

  combined = constrain(combined, 0, 1);

  const palette = pairPriceData[pair].palette;

  const paletteIndex = combined * (palette.length - 1);
  const lowerIndex = floor(paletteIndex);
  const upperIndex = min(lowerIndex + 1, palette.length - 1);
  const fraction = paletteIndex - lowerIndex;

  const color1 = color(palette[lowerIndex]);
  const color2 = color(palette[upperIndex]);

  const baseColor = lerpColor(color1, color2, fraction);

  // Apply depth effect based on wave position and price status
  // combined (0-1) represents wave position: 0 = trough, 1 = peak
  const animState = getAnimationState();
  const priceIntensity = getCurrentPriceIntensity(animState);
  const finalColor = applyDepthEffect(baseColor, combined, priceIntensity);

  fill(finalColor);
  noStroke();
  rect(x * cellSize, y * cellSize, cellSize, cellSize);
}

