// format big-integer string to decimal (safe for big numbers); passes through already-formatted values
function fmtUnits(v, d) {
  var s = String(v || "0");
  if (s.indexOf('.') >= 0) return s;
  s = s.padStart(d + 1, '0');
  var i = s.slice(0, s.length - d);
